# main.tf — Production web application stack
# HCL (HashiCorp Configuration Language) with remote state backend

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }

  # Remote state: S3 bucket + DynamoDB lock for team safety
  backend "s3" {
    bucket         = "acme-terraform-state"
    key            = "prod/web-app/main.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-state-lock"
    encrypt        = true  # KMS encryption at rest
  }
}

provider "aws" {
  region = var.aws_region
  # Credentials via environment: AWS_ACCESS_KEY_ID + AWS_SECRET_ACCESS_KEY
  # Or via IAM role if running in EC2/ECS/GitHub Actions OIDC
}

# ── Variables (parameterize for dev / staging / prod reuse) ──
variable "aws_region"      { default = "us-east-1" }
variable "env"             { description = "Environment name (dev/staging/prod)" }
variable "instance_count"  { type = number; default = 2 }
variable "instance_type"   { default = "t3.micro" }
variable "app_ami"         { description = "AMI ID for web tier" }

# ── Locals: derived values used in multiple places (DRY) ──
locals {
  name_prefix = "acme-${var.env}"
  common_tags = {
    Environment = var.env
    ManagedBy   = "terraform"
    Project     = "acme-web"
  }
}

# ── Data sources: read existing resources (not managed here) ──
data "aws_vpc" "main" {
  tags = { Name = "${local.name_prefix}-vpc" }
}

data "aws_subnets" "private" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.main.id]
  }
  tags = { Tier = "private" }
}

# ── Resources ──
resource "aws_security_group" "web" {
  name   = "${local.name_prefix}-web-sg"
  vpc_id = data.aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web" {
  count         = var.instance_count
  ami           = var.app_ami
  instance_type = var.instance_type
  subnet_id     = data.aws_subnets.private.ids[count.index % length(data.aws_subnets.private.ids)]
  vpc_security_group_ids = [aws_security_group.web.id]

  # Implicit dependency: Terraform creates the SG before the instances
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-web-${count.index}"
  })
}

resource "aws_lb_target_group_attachment" "web" {
  count            = var.instance_count
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = aws_instance.web[count.index].id
  port             = 443
}

# ── Outputs: expose values to other systems / humans ──
output "lb_dns_name" {
  description = "Load balancer DNS name for DNS record creation"
  value       = aws_lb.main.dns_name
}

output "web_instance_ids" {
  description = "IDs of web tier instances for health checks"
  value       = aws_instance.web[*].id
}

# packer/web-server.pkr.hcl — Build the web server AMI
# Run: packer build web-server.pkr.hcl
# Output: ami-0abc123def456789 (new AMI ID to put in Terraform)

packer {
  required_plugins {
    amazon = { source = "github.com/hashicorp/amazon", version = "~> 1" }
  }
}

variable "region"       { default = "us-east-1" }
variable "app_version"  { description = "Git tag to build" }

source "amazon-ebs" "web" {
  region        = var.region
  source_ami_filter {
    filters = { name = "al2023-ami-*-x86_64" }
    owners  = ["amazon"]
    most_recent = true
  }
  instance_type = "t3.small"
  ssh_username  = "ec2-user"
  ami_name      = "acme-web-${var.app_version}-{{timestamp}}"
  tags          = { Version = var.app_version, ManagedBy = "packer" }
}

build {
  sources = ["source.amazon-ebs.web"]

  provisioner "shell" {
    inline = [
      "sudo dnf update -y",
      "sudo dnf install -y nginx nodejs",
      "sudo systemctl enable nginx"
    ]
  }

  provisioner "file" {
    source      = "../dist/app-${var.app_version}.tar.gz"
    destination = "/tmp/app.tar.gz"
  }

  provisioner "shell" {
    inline = [
      "sudo tar -xzf /tmp/app.tar.gz -C /var/www/html",
      "sudo systemctl start nginx"
    ]
  }
}
